contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[2][] calldata customAttributes) public {
        // read the round state before the call through the public getters
        uint256 roundBefore = c.roundId();
        uint32 claimedBefore = c.numRoundsClaimed(address(this));
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // empty model arrays are fine: no winner addresses exist for this caller,
        // so mintFromMergingPool is never invoked and nothing is indexed
        string[] memory uris = new string[](0);
        string[] memory types = new string[](0);

        bool reverted;
        c.claimRewards(uris, types, customAttributes);
        reverted = false;

        uint32 claimedAfter = c.numRoundsClaimed(address(this));
        uint256 unclaimedAfter = c.getUnclaimedRewards(address(this));
        uint256 roundAfter = c.roundId();

        // General rule: a non-winning claimer's claim never reverts; the contract
        // records that every round up to the current roundId has been claimed by
        // them, and their unclaimed reward count is unchanged by the call.
        assert(
            !reverted &&
            claimedAfter == roundAfter &&
            unclaimedAfter == unclaimedBefore &&
            roundAfter == roundBefore &&
            claimedAfter >= claimedBefore
        );
    }

    receive() external payable {}
}

