contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public {
        // Precondition: no winners have been picked yet, so there is nothing to claim.
        require(c.roundId() == 0);

        uint32 claimedBefore = c.numRoundsClaimed(address(this));
        uint256 unclaimedBefore = c.getUnclaimedRewards(address(this));

        // State-changing call: must succeed (there is no revert path when roundId == 0)
        // and must leave the claimer's accounting untouched.
        c.claimRewards(modelURIs, modelTypes, customAttributes);

        assert(
            claimedBefore == 0 &&
            unclaimedBefore == 0 &&
            c.numRoundsClaimed(address(this)) == 0 &&
            c.getUnclaimedRewards(address(this)) == 0
        );
    }

    receive() external payable {}
}

