contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address admin, uint256 newWinnersPerPeriodAmount) public payable {
        require(admin != address(0));
        // The test contract is the owner, so it may toggle admin access.
        c.adjustAdminAccess(admin, true);
        bool revertedWithAccess;
        try c.updateWinnersPerPeriod(newWinnersPerPeriodAmount) { revertedWithAccess = false; } catch { revertedWithAccess = true; }
        c.adjustAdminAccess(admin, false);
        bool revertedWithoutAccess;
        try c.updateWinnersPerPeriod(newWinnersPerPeriodAmount) { revertedWithoutAccess = false; } catch { revertedWithoutAccess = true; }
        // Any admin-granted address may update winnersPerPeriod for any value,
        // and once its admin access is revoked the same call must revert.
        assert(!revertedWithAccess && revertedWithoutAccess && c.winnersPerPeriod() == newWinnersPerPeriodAmount);
    }
    receive() external payable {}
}

