contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address claimer) public payable {
        require(true);
        uint256 winnersPerPeriod = c.winnersPerPeriod();
        uint256 roundId = c.roundId();
        uint32 alreadyClaimed = c.numRoundsClaimed(claimer);
        uint256 unclaimed = c.getUnclaimedRewards(claimer);
        // Each fully-selected (unclaimed) round awards at most winnersPerPeriod rewards,
        // and rounds already claimed were counted in numRoundsClaimed, so unclaimed
        // rewards can never exceed (roundId - numRoundsClaimed) * winnersPerPeriod.
        assert(
            roundId >= alreadyClaimed &&
            unclaimed <= (roundId - uint256(alreadyClaimed)) * winnersPerPeriod
        );
    }
    receive() external payable {}
}

