    constructor(C _c) { c = _c; }
    function run(address admin, uint256 newWinnersPerPeriod) public {
        require(admin != address(this));
        // Initially only the owner (this contract) is admin
        bool beforeGrant = c.isAdmin(admin);
        // Grant admin access
        c.adjustAdminAccess(admin, true);
        bool afterGrant = c.isAdmin(admin);
        // Revoke admin access
        c.adjustAdminAccess(admin, false);
        bool afterRevoke = c.isAdmin(admin);
        // Owner can update winnersPerPeriod to any value
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        uint256 stored = c.winnersPerPeriod();
        assert(!beforeGrant && afterGrant && !afterRevoke && stored == newWinnersPerPeriod);
    }
}

