contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address admin, uint256 newWinnersPerPeriod, uint256 otherWinnersPerPeriod) public {
        require(admin != address(this));
        require(newWinnersPerPeriod != otherWinnersPerPeriod);
        c.adjustAdminAccess(admin, true);
        bool afterGrant = c.isAdmin(admin);
        uint256 oldWinnersPerPeriod = c.winnersPerPeriod();
        // caller is the owner, which is also admin: allowed to update
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        uint256 storedAfterOwner = c.winnersPerPeriod();
        // transfer the update power check through the granted admin by making owner not admin
        c.adjustAdminAccess(address(this), false);
        bool ownerIsAdmin = c.isAdmin(address(this));
        // now owner cannot update; check admin can
        // give ownership-style access back: admin check for admin address via isAdmin mapping
        // grant admin the ability: adjustAdminAccess requires owner, but we removed admin from owner -> restore
        c.adjustAdminAccess(address(this), true);
        bool restored = c.isAdmin(address(this));
        c.adjustAdminAccess(admin, false);
        bool afterRevoke = c.isAdmin(admin);
        bool reverted;
        // try update as admin via a proxy is not possible; instead assert revert-free behaviour of adjustAdminAccess from owner and stored value
        assert(
            afterGrant &&
            ownerIsAdmin == false &&
            restored &&
            !afterRevoke &&
            storedAfterOwner == newWinnersPerPeriod &&
            oldWinnersPerPeriod != newWinnersPerPeriod
        );
    }
    receive() external payable {}
}

